CREATE TABLE admin_statuses (
  id          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        VARCHAR2(100) NOT NULL UNIQUE,
  sort_order  NUMBER DEFAULT 0 NOT NULL
);

