  body                 CLOB,
  created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by           VARCHAR2(100),
  modified_by          VARCHAR2(100)
);

-- Source: FM table "Administration" (360 records, 31 schema fields)
CREATE TABLE memorial_minutes (
  id                                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fm_id                                VARCHAR2(50) UNIQUE NOT NULL, -- Original FM UUID for migration tracking
  first_name                           VARCHAR2(100),
  middle_name                          VARCHAR2(100),
  last_name                            VARCHAR2(100),
  degrees                              VARCHAR2(200),
  date_of_death                        DATE,
  date_informed                        DATE,
  informed_by                          VARCHAR2(200),
  next_of_kin                          VARCHAR2(500),
  huid                                 VARCHAR2(20),
  hms_academic_title                   VARCHAR2(200),
  status_id                            NUMBER REFERENCES admin_statuses(id),
  administration_comments              CLOB,
  hms_institution                      VARCHAR2(200),
  internal_ofa_announcement_date       DATE,
  hms_half_staff_announcement_date     DATE,
  qualifies_for_fom_reading            CHAR(1) CHECK (qualifies_for_fom_reading IN ('Y', 'N')),
  fom_reading_date                     DATE,
  current_dept_head_name               VARCHAR2(200),
  current_dept_head_email              VARCHAR2(200),
  current_dept_head_admin_email        VARCHAR2(200),
  dept_head_outreach_date              DATE,
  name_of_mm_chair                     VARCHAR2(200),
  mm_accepted_date                     DATE,
  mm_photo_obtained                    CHAR(1) CHECK (mm_photo_obtained IN ('Y', 'N')),
  mm_posted_to_ofa_website_date        DATE,
  mm_chair_photo_file_name             VARCHAR2(500), -- Container field becomes file reference
  committee_membership_comments        CLOB,
  committee_milestone_comments         CLOB,
  milestone_guidelines_sent            CHAR(1) CHECK (milestone_guidelines_sent IN ('Y', 'N')),
  milestone_3_mos_status_req_sent      CHAR(1) CHECK (milestone_3_mos_status_req_sent IN ('Y', 'N')),
  milestone_6_mos_status_req_sent      CHAR(1) CHECK (milestone_6_mos_status_req_sent IN ('Y', 'N')),
  milestone_9_mos_status_req_sent      CHAR(1) CHECK (milestone_9_mos_status_req_sent IN ('Y', 'N')),
  milestone_draft_mm_received_date     DATE,
  milestone_cmte_members_thanked_date  DATE,
  milestone_final_accepted_date        DATE,
  created_at                           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at                           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by                           VARCHAR2(100),
  modified_by                          VARCHAR2(100)
);

-- Source: FM table "Cmte_Membership" (1606 records, 14 schema fields)
CREATE TABLE committee_members (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fm_id                 VARCHAR2(50) UNIQUE NOT NULL, -- Original FM UUID
  memorial_minute_id    NUMBER NOT NULL REFERENCES memorial_minutes(id) ON DELETE CASCADE,
  first_name           VARCHAR2(100),
  middle_initial       VARCHAR2(10),
  last_name            VARCHAR2(100),
  degrees              VARCHAR2(200),
  status_id            NUMBER REFERENCES member_statuses(id),
  academic_title       VARCHAR2(200),
  email_address        VARCHAR2(200),
  mailing_address      CLOB,
  committee_role_id    NUMBER REFERENCES member_roles(id),
  membership_comments  CLOB,
  created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by           VARCHAR2(100),
  modified_by          VARCHAR2(100)
);

-- Source: FM table "Cmte_Milestones" (1656 records, 4 schema fields)
CREATE TABLE milestones (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fm_id                 VARCHAR2(50) UNIQUE NOT NULL, -- Original FM UUID
  memorial_minute_id    NUMBER NOT NULL REFERENCES memorial_minutes(id) ON DELETE CASCADE,
  milestone            VARCHAR2(200),
  milestone_date       DATE,
  note                 CLOB,
  created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by           VARCHAR2(100),
  modified_by          VARCHAR2(100)
);

-- Source: FM table "Cmte_Correspondence" (3 records, 7 schema fields)
CREATE TABLE correspondence (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fm_id                 VARCHAR2(50) UNIQUE NOT NULL, -- Original FM UUID
  committee_member_id   NUMBER REFERENCES committee_members(id) ON DELETE SET NULL,
  memorial_minute_id    NUMBER NOT NULL REFERENCES memorial_minutes(id) ON DELETE CASCADE,
  subject              VARCHAR2(500),
  date_sent            DATE,
  decision             VARCHAR2(50) CHECK (decision IN ('Accept', 'Decline')),
  note                 CLOB,
  document_file_name   VARCHAR2(500), -- Container field becomes file reference
  created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by           VARCHAR2(100),
  modified_by          VARCHAR2(100)
);

-- Source: FM table "Cmte_Reference_Documents" (103 records, 6 schema fields)
CREATE TABLE reference_documents (
  id                    NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  fm_id                 VARCHAR2(50) UNIQUE NOT NULL, -- Original FM UUID
  memorial_minute_id    NUMBER NOT NULL REFERENCES memorial_minutes(id) ON DELETE CASCADE,
  document_title       VARCHAR2(500),
  date_received        DATE,
  document_file_name   VARCHAR2(500), -- Container field becomes file reference
  document_comment     CLOB,
  created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  created_by           VARCHAR2(100),
  modified_by          VARCHAR2(100)
);

