-- =============================================================================
-- VIEWS (for computed/calculated fields)
-- =============================================================================

-- Memorial Minutes with formatted name (replaces FM calculated field)
CREATE OR REPLACE VIEW v_memorial_minutes_with_names AS
SELECT
  mm.*,
  CASE
    WHEN middle_name IS NOT NULL THEN
      first_name || ' ' || middle_name || ' ' || last_name
    ELSE
      first_name || ' ' || last_name
  END AS full_name,
  status.name as status_name
FROM memorial_minutes mm
LEFT JOIN admin_statuses status ON mm.status_id = status.id;

-- Committee members with formatted name and status
CREATE OR REPLACE VIEW v_committee_members_with_names AS
SELECT
  cm.*,
  CASE
    WHEN middle_initial IS NOT NULL THEN
      first_name || ' ' || middle_initial || ' ' || last_name
    ELSE
      first_name || ' ' || last_name
  END AS full_name,
  ms.name as status_name,
  mr.name as role_name,
  -- Is Chair calculation (replaces FM calculated field)
  CASE
    WHEN mr.name = 'Chair' AND ms.name = 'Accept' THEN 1
    ELSE 0
  END as is_chair
FROM committee_members cm
LEFT JOIN member_statuses ms ON cm.status_id = ms.id
LEFT JOIN member_roles mr ON cm.committee_role_id = mr.id;

-- Committee chair view (replaces complex FM relationship)
CREATE OR REPLACE VIEW v_committee_chairs AS
SELECT
  memorial_minute_id,
  full_name as chair_name,
  email_address as chair_email
FROM v_committee_members_with_names
WHERE is_chair = 1;

